mapper.select:
WITH RECURSIVE tree (id,parent_id,name,html_uri,button_code, sort_no, icon, last_level, app_id,api_url,create_time,permissionType,permissionKey) AS ( select d.* from (SELECT id, parent_id, name, null as html_uri,button_code, sort_no, icon, last_level, app_id,api_url,create_time,1 as permissionType,permission_key as permissionKey FROM ins_button_permission where filter_status=0 union all SELECT id, parent_id, name, html_uri, null as button_code,sort_no, icon, last_level, app_id,api_url, create_time,2 as permissionType,permission_key as permissionKey FROM ins_menu_permission where del_flag=0 and filter_status=0) d where d.id in
#{item}
union all select f.* from ( SELECT id, parent_id, name, null as html_uri,button_code, sort_no, icon, last_level, app_id,api_url,create_time,1 as permissionType,permission_key as permissionKey FROM ins_button_permission where filter_status=0 union all SELECT id, parent_id, name, html_uri, null as button_code,sort_no, icon, last_level, app_id,api_url, create_time,2 as permissionType,permission_key as permissionKey FROM ins_menu_permission where del_flag=0 and filter_status=0) f INNER JOIN tree t ON t.parent_id = f.id ) SELECT * FROM tree group by id;
